async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let eof = false;
  let failed = false;
  let fragments = [];

  async function visitLine(text) {
    line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return true;
    }

    accepted++;
    return (await visitor({ line, value })) !== false;
  }

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        eof = true;
        const tail = decoder.decode();
        if (tail.length > 0) fragments.push(tail);

        if (fragments.length > 0) {
          const text = fragments.join("");
          fragments = [];
          if (!(await visitLine(text))) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      let start = 0;

      while (start < value.length) {
        const end = value.indexOf(10, start);

        if (end === -1) {
          const fragment = decoder.decode(value.subarray(start), {
            stream: true
          });
          if (fragment.length > 0) fragments.push(fragment);
          break;
        }

        const text =
          fragments.join("") +
          decoder.decode(value.subarray(start, end));
        fragments = [];

        if (!(await visitLine(text))) {
          return { accepted, rejected, stopped: true };
        }

        start = end + 1;
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    try {
      if (!eof || failed) await reader.cancel();
    } finally {
      reader.releaseLock();
    }
  }
}
